-- Seed: 30 factions and 5 aliases (generated by scripts/print-seed-sql.ts)
ON CONFLICT ("name") DO NOTHING;
--> statement-breakpoint
SELECT v.alias, f.id FROM (VALUES
  ('necro virus', 'Nekro Virus'),
  ('the yssaril triobes', 'Yssaril Tribes'),
  ('the titan of ul', 'Titans of Ul'),
  ('the vuil''rairh cabal', 'Vuil''raith Cabal'),
  ('saar', 'Clan of Saar')
) AS v(alias, faction_name)
JOIN "factions" f ON f.name = v.faction_name
ON CONFLICT ("alias") DO NOTHING;
